function method strength(extension: string) : int
{
    var capCount := 0;
    var smCount := 0;

    // Count uppercase and lowercase letters
    var i := 0;
    while i < |extension|
        invariant 0 <= i <= |extension|
        invariant capCount >= 0 && smCount >= 0
    {
        if extension[i] >= 'A' && extension[i] <= 'Z' {
            capCount := capCount + 1;
        } else if extension[i] >= 'a' && extension[i] <= 'z' {
            smCount := smCount + 1;
        }
        i := i + 1;
    }

    capCount - smCount;
}
